"""Build the concise, accessible homepage from audited public data."""
import json,pathlib,html
root=pathlib.Path(__file__).resolve().parents[1]
YEARS=[2015,2016,2017,2018,2019,2021,2022,2023,2024,2025]
original=json.loads((root/'data/mwc-2011-2025.json').read_text())
season_data=json.loads((root/'data/mwc-2011-2025-seasons.json').read_text())
audit=json.loads((root/'data/mwc-super-audit-2011-2025.json').read_text())
A=[]
for old in original:
 selected=[x for x in season_data if x['team']==old['team'] and x['year'] in YEARS]
 assert len(selected)==10
 row=dict(team=old['team'],**{k:sum(x[k] for x in selected) for k in ['wins','losses','games','pf','pa']})
 row['super_losses']=sum(x['superLoss'] for x in audit if x['team']==row['team'] and x['year'] in YEARS)
 row.update(loss_rate=round(100*row['losses']/row['games'],1),super_rate=round(100*row['super_losses']/row['games'],1),margin=round((row['pf']-row['pa'])/row['games'],1))
 A.append(row)
import csv
(root/'data/mwc-last-10.json').write_text(json.dumps(A,indent=2))
with (root/'data/mwc-last-10.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=A[0].keys());w.writeheader();w.writerows(A)
seasons=[x for x in json.loads((root/'data/seasons.json').read_text()) if x['year'] in YEARS]
supers=[x for x in json.loads((root/'data/super-losses.json').read_text()) if x['year'] in YEARS]
S=True
lu=next(r for r in A if r['team']=='Lawrence')
def signed(n):return f'{n:+.1f}'.replace('-','−')
def chart(key,maximum,margin=False):
 rows=sorted(A,key=lambda r:r[key] if margin else -r[key]);h='<div class="chart '+('margin' if margin else '')+'" role="group" aria-label="'+{'loss_rate':'Loss rates','super_rate':'SUPER LOSS rates','margin':'Average scoring margins'}[key]+', 2015–2019 and 2021–2025">'
 for r in rows:
  v=r[key];label=signed(v) if margin else f'{v:.1f}%';width=abs(v)/maximum*(50 if margin else 100);left=50-width if margin and v<0 else 50 if margin else 0
  detail=(f'{r["wins"]} wins; {r["losses"]} losses in {r["games"]} games' if key=='loss_rate' else f'{r["super_losses"]} SUPER LOSSES in {r["games"]} games' if key=='super_rate' else f'{r["pf"]} points scored; {r["pa"]} allowed in {r["games"]} games')
  h+=f'<div class="chart-row {"lawrence" if r["team"]=="Lawrence" else ""}" title="{detail}"><span>{r["team"]}</span><div class="track" aria-hidden="true"><i class="bar" style="left:{left:.3f}%;width:{width:.3f}%"></i></div><strong>{label}</strong></div>'
 return h+'</div><div class="axis" aria-hidden="true"><span>'+('−'+str(maximum) if margin else '0%')+'</span>'+('<span>0</span>' if margin else '')+'<span>'+('+' if margin else '')+str(maximum)+('' if margin else '%')+'</span></div>'
rate=chart('loss_rate',100);margin=chart('margin',30,True)
if S:
 rank=1+sum(r['super_rate']>lu['super_rate'] for r in A);ordinal={1:'Highest',2:'Second-highest',3:'Third-highest',4:'Fourth-highest',5:'Fifth-highest'}.get(rank,f'Rank {rank} of 10')
 superchart=chart('super_rate',max(15,5*((max(r['super_rate'] for r in A)+4.999)//5)));supervalue=f'{lu["super_rate"]:.1f}%';superfinding=f'{ordinal} · {lu["super_losses"]} of {lu["games"]} games'
else:superchart='<div class="pending">Full-period boxscore audit in progress. No comparative rate is shown until coverage is complete.</div>';supervalue='Audit pending';superfinding='2011–2025 · every defeat being checked'
rows=''
for r in sorted(A,key=lambda r:-r['losses']):
 rows+=f'<tr class="{"lawrence" if r["team"]=="Lawrence" else ""}"><th scope="row">{r["team"]}</th><td>{r["losses"]}</td><td>{r["wins"]}</td><td>{r["games"]}</td><td>{r["loss_rate"]:.1f}%</td><td>{r.get("super_losses","Pending")}</td><td>{str(r.get("super_rate","Pending"))+("%" if S else "")}</td><td>{signed(r["margin"])}</td></tr>'
victory=''.join(f'<div class="victory-year"><div class="victory-column">'+(f'<strong>{s["wins"]}</strong><div class="victory-bar" style="height:{s["wins"]*22}px" aria-hidden="true"></div>' if s['games'] else '<span class="no-season">No season</span>')+f'</div><span class="victory-label">{s["year"]}{"*" if s["year"]==2026 else ""}</span></div>' for s in seasons)
superrows=''.join(f'<tr><td>{s["year"]}</td><th scope="row"><a href="{s["source"]}">{s["opponent"]}</a></th><td>{s["lu_points"]}–{s["opponent_points"]}</td><td>{s["lu_first_downs"]}</td><td>{s["opponent_touchdowns"]}</td></tr>' for s in supers)
share='''<div class="share-control"><button id="share-button" type="button" aria-label="Share this report"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 16V3m-4 4 4-4 4 4M5 13v7a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-7"/></svg>Share</button><span id="share-status" role="status" aria-live="polite"></span><div id="share-fallback" hidden><label for="share-url">Copy this link</label><input id="share-url" type="url" readonly value="https://omatty123.github.io/lu-football-review/"></div></div>'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lawrence football: ten seasons, twelve wins</title><meta name="description" content="Lawrence football compared with every current Midwest Conference team over the last ten completed played seasons (2015–2019 and 2021–2025): loss rates, SUPER LOSS rates, scoring margins, and victories."><link rel="stylesheet" href="fonts.css"><link rel="stylesheet" href="story.css"><script defer src="story.js"></script></head><body><a class="skip" href="#main">Skip to report</a><div class="wrap"><header class="masthead"><a class="brand" href="#main">LAWRENCE FOOTBALL</a><nav aria-label="Report navigation"><a href="#conference-history">Compare teams</a><a href="#victories">Victories</a><a href="full-report.html">Full report</a></nav>{share}</header><main id="main">
<section class="opening"><div><p class="eyebrow">Last 10 completed played seasons · 2015–2019 + 2021–2025</p><h1>Ten seasons. Twelve wins.</h1><p class="lede">Lawrence went <strong>12–85</strong>: the <strong>highest loss rate</strong> among the ten comparison teams. Its SUPER LOSS rate and scoring margin are both second-worst.</p></div><aside class="streak" aria-label="Current losing streak"><strong>19</strong><span>STRAIGHT LOSSES</span><small>Through Oct. 17, 2026.<br>Last win: Oct. 19, 2024.</small></aside></section>
<section class="comparison" id="conference-history"><div class="section-heading"><h2>KEY METRICS OF LAWRENCE FOOTBALL FAILURE</h2><p class="legend"><b>Lawrence</b> in red · peers in gray</p></div><div class="compare-grid">
<article class="metric" id="loss-rate"><h3>Loss rate</h3><p class="metric-subtitle">The share of games a team lost.</p><div class="metric-value">87.6%</div><p class="metric-finding">Highest · 85 of 97 games</p>{rate}</article>
<article class="metric" id="super-loss-rate"><h3>SUPER LOSS rate</h3><p class="metric-subtitle">Losses where opponent touchdowns exceeded the team’s first downs, as a share of all games.</p><div class="metric-value">{supervalue}</div><p class="metric-finding">{superfinding}</p>{superchart}</article>
<article class="metric" id="scoring-margin"><h3>Scoring margin</h3><p class="metric-subtitle">Points scored minus points allowed, per game.</p><div class="metric-value">−25.4</div><p class="metric-finding">Second-worst · Grinnell is worst at −27.8</p>{margin}</article></div>
<p class="chart-note">2015–2019 and 2021–2025 totals, including nonconference and postseason games. The canceled 2020 season and incomplete 2026 season are excluded. SUPER LOSS is this report’s measure, not an official NCAA statistic. Each graph is ranked separately; values are rounded to one decimal.</p>
<details class="details"><summary>See exact totals, losses, and rates for all ten teams</summary><div class="table-scroll" tabindex="0" role="region" aria-label="Full comparison table; scroll horizontally"><table><caption>Last 10 completed played seasons · sorted by total losses</caption><thead><tr><th>Team</th><th>Losses</th><th>Wins</th><th>Games</th><th>Loss rate</th><th>Super losses</th><th>Super rate</th><th>Margin/game</th></tr></thead><tbody>{rows}</tbody></table></div><p><a href="data/mwc-last-10.csv" download>All comparison data</a> · <a href="full-report.html#conference-history">2011–2025 comparison</a> · <a href="full-report.html#conference">2025 comparison</a></p></details></section>
<section class="story-section" id="victories"><div class="section-heading"><h2>VICTORY GRAPH</h2><p>No more than three wins in any season shown. Only one victory since 2021.</p></div><div class="victory-graph" id="victory-graph" role="group" aria-label="Lawrence victories in the last ten completed played seasons">{victory}</div><p class="chart-note">Ten completed played seasons. 2020 was canceled; 2026 is still in progress. <a href="full-report.html#seasons">Explore every season and game →</a></p></section>
<section class="story-section" id="super-losses"><div class="spotlight"><div><p class="eyebrow">Chicago 66, Lawrence 0 · Oct. 11, 2025</p><h2>One game makes the gap concrete.</h2><p>Chicago scored nine touchdowns. Lawrence earned one first down. Five of Lawrence’s nine games in 2025 were SUPER LOSSES.</p><a href="{next(s['source'] for s in supers if s['year']==2025 and s['opponent']=='Chicago')}">Official box score ↗</a></div><div class="score-contrast"><div><strong>9</strong><span>CHICAGO TOUCHDOWNS</span><small>Offense, defense, and special teams</small></div><div><strong>1</strong><span>LAWRENCE FIRST DOWN</span><small>Total for the entire game</small></div></div></div><details class="details"><summary>See all 14 Lawrence SUPER LOSSES in these ten seasons</summary><div class="table-scroll" tabindex="0" role="region" aria-label="Lawrence super losses; scroll horizontally"><table><thead><tr><th>Year</th><th>Opponent / source</th><th>LU score</th><th>LU first downs</th><th>Opponent TDs</th></tr></thead><tbody>{superrows}</tbody></table></div></details></section>
<section class="story-section evidence" id="evidence"><h2>The evidence behind the graphs</h2><p>Official conference records and school boxscores. Completed games only. Every team is compared over 2015–2019 and 2021–2025; rates are weighted by games.</p><details class="details"><summary>Sources, definitions, and coverage</summary><ul><li><strong>Comparison group:</strong> the ten 2025 MWC teams, including Chicago’s 2015–2016 seasons before it joined. <a href="full-report.html#conference-history">Full 2011–2025 comparison, former members, and membership-period totals</a> remain in the full report.</li><li><strong>Loss rate:</strong> losses ÷ all completed games. <strong>SUPER LOSS rate:</strong> qualifying losses ÷ all completed games, including wins in the denominator. Opponent total touchdowns must be strictly greater than the losing team’s first downs. Equality does not count.</li><li><strong>Scoring margin:</strong> total points scored minus total points allowed, divided by games. All points count; this is not a pure measure of the defense. Opponent strength is not adjusted.</li><li><strong>Unequal schedules:</strong> canceled games are excluded. Grinnell played three games in 2019 and eight in 2022. No team played a 2020 MWC season.</li><li><strong>Audit coverage:</strong> The underlying 2011–2025 audit checked all 761 defeats and found 54 SUPER LOSSES. These graphs use only the ten selected seasons. Scoring-summary checks agreed in 759 cases. Two malformed summaries were resolved using team-statistics totals; neither game qualifies as a SUPER LOSS. Row-level notes are in the audit data.</li><li><strong>Audit:</strong> <a href="data/mwc-2011-2025-seasons.csv">160 team-season rows with sources</a> · <a href="data/mwc-super-audit-2011-2025.json">Every audited defeat and boxscore</a> · <a href="https://midwestconference.org/sports/2011/4/14/FB_0414112406.aspx">Official MWC archive</a>.</li></ul></details><p><a href="full-report.html">Read the full report: scoring trends, history, coaching, sources →</a></p></section></main><footer>Independent statistical review · Snapshot: October 18, 2026 · <a href="https://github.com/omatty123/lu-football-review">Data and revision history</a></footer></div></body></html>'''
(root/'index.html').write_text(page)
print('Built concise homepage; SUPER LOSS rates '+('complete' if S else 'pending, not ready to publish'))
